tasks.verifier:
import inspect
from target import parse_record
assert str(inspect.signature(parse_record)) == '(text)'
assert parse_record('  {"name": "中文", "count": 0} \n') == {'name': '中文', 'count': 0}
for text in ('[]', 'null', '1', '"x"', '{"secret":', '{bad}'):
    try:
        parse_record(text)
    except ValueError as exc:
        assert str(exc) == 'E_RECORD', repr(exc)
    else:
        raise AssertionError('invalid record accepted')
print('constraints passed')

import inspect
