assert str(inspect.signature(parse_duration)) == '(text)'
for text, expected in [(' 1.25s ',1250), ('0ms',0), ('1.0ms',1), ('9007199254740993ms',9007199254740993), ('0.001s',1)]:
    assert parse_duration(text) == expected, text
    assert type(parse_duration(text)) is int
for text in ('-1ms','1','1m','NaNs','infs','0.1ms','0.0001s',''):
