        parse_duration(text)
    except ValueError as exc:
        assert str(exc) == 'E_DURATION', repr(exc)
    else:
        raise AssertionError('invalid duration accepted: ' + text)
print('constraints passed')

tasks.source:
def update_settings(current, changes):
    current.update({k: v for k, v in changes.items() if v})
    return current

tasks.smoke:
from target import update_settings
assert update_settings({'port': 80}, {'port': 443}) == {'port': 443}
print('smoke passed')

tasks.verifier:
import copy, inspect
from target import update_settings
assert str(inspect.signature(update_settings)) == '(current, changes)'
current = {'a': 1, 'b': True, 'c': 'old', 'd': 4}
changes = {'a': 0, 'b': False, 'c': '', 'd': None}
before = copy.deepcopy(current), copy.deepcopy(changes)
result = update_settings(current, changes)
assert result == changes and result is not current
assert (current, changes) == before
try:
    update_settings(current, {'a': 9, 'unknown': 1})
except ValueError as exc:
    assert str(exc) == 'E_SETTING'
else:
    raise AssertionError('unknown key accepted')
assert current == before[0]
assert update_settings({}, {}) == {}
print('constraints passed')
